<?php get_header(); ?><main class="inner-page"><div class="container-xl py-5"><?php estatein_breadcrumbs(); ?><div class="row g-5"><div class="col-lg-7"><div class="property-gallery"><?php for($i=1;$i<=6;$i++){ $html=estatein_image('gallery_'.$i,'large',false,'gallery-image'); if($html) echo $html; } if(!has_post_thumbnail() && !estatein_field('gallery_1')) echo '<div class="gallery-placeholder"></div>'; ?></div></div><div class="col-lg-5"><span class="section-kicker"><?php echo esc_html(estatein_field('property_status_label',false,'For Sale')); ?></span><h1><?php the_title(); ?></h1><p class="lead text-secondary"><?php echo esc_html(estatein_field('short_excerpt',false,get_the_excerpt())); ?></p><div class="detail-price"><small>Price</small><strong><?php echo esc_html(estatein_currency(estatein_field('price'))); ?></strong></div><div class="property-meta large"><span><?php echo esc_html(estatein_field('bedrooms','', '—')); ?> Bedrooms</span><span><?php echo esc_html(estatein_field('bathrooms','', '—')); ?> Bathrooms</span><span><?php echo esc_html(estatein_field('property_size','', '—')); ?> <?php echo esc_html(estatein_field('property_size_unit',false,'sq ft')); ?></span></div><?php estatein_render_ninja_form('property_form_shortcode'); ?></div></div><section class="detail-section"><div class="row g-5"><div class="col-lg-7"><h2>Overview</h2><div class="rich-text"><?php the_content(); ?></div><h3 class="mt-5">Highlights</h3><ul class="highlight-list"><?php for($i=1;$i<=6;$i++):$v=estatein_field('property_highlight_'.$i);if($v): ?><li><?php echo esc_html($v); ?></li><?php endif;endfor; ?></ul></div><div class="col-lg-5"><div class="detail-panel"><h3>Property Details</h3><dl><?php foreach(['property_size'=>'Property Size','lot_size'=>'Lot Size','build_year'=>'Build Year','parking_spaces'=>'Parking Spaces','address'=>'Address','city'=>'City','state'=>'State','country'=>'Country'] as $k=>$label):$v=estatein_field($k);if($v!==''): ?><div><dt><?php echo esc_html($label); ?></dt><dd><?php echo esc_html($v); ?><?php if($k==='property_size')echo ' '.esc_html(estatein_field('property_size_unit',false,'sq ft')); ?></dd></div><?php endif;endforeach; ?></dl></div></div></div></section><section class="detail-section"><div class="row g-4"><div class="col-lg-7"><div class="detail-panel"><h3>Comprehensive Pricing</h3><dl><?php foreach(['price_per_sqft'=>'Price per Sq Ft','hoa_fee'=>'HOA / Association Fee','property_tax_annual'=>'Annual Property Tax','insurance_annual'=>'Annual Insurance','maintenance_monthly'=>'Monthly Maintenance','utilities_monthly'=>'Monthly Utilities','down_payment_percent'=>'Suggested Down Payment %','closing_cost_percent'=>'Estimated Closing Costs %','estimated_monthly_payment'=>'Estimated Monthly Payment'] as $k=>$label):$v=estatein_field($k);if($v!==''): ?><div><dt><?php echo esc_html($label); ?></dt><dd><?php echo esc_html($k==='down_payment_percent'||$k==='closing_cost_percent'?$v.'%':estatein_currency($v)); ?></dd></div><?php endif;endforeach; ?></dl><?php if(estatein_field('pricing_notes'))echo '<p class="mt-3">'.esc_html(estatein_field('pricing_notes')).'</p>'; ?></div></div><div class="col-lg-5"><div class="detail-panel"><h3>Location</h3><p><?php echo nl2br(esc_html(estatein_field('address'))); ?></p><?php if(estatein_field('map_embed')): ?><div class="ratio ratio-4x3"><iframe src="<?php echo esc_url(estatein_field('map_embed')); ?>" loading="lazy" style="border:0"></iframe></div><?php endif; ?></div></div></div></section></div></main><?php get_footer(); ?>
